// bin/model-artefacts.mjs — every rule in both directions, over fixtures built here at test time.
//
// The pickles are hand-assembled opcode streams rather than files generated by Python, so the test
// carries no interpreter dependency and the bytes under test are exactly the bytes in this file.
// The zip is assembled the same way (local headers, central directory, end record), once STORED
// and once DEFLATE, because torch checkpoints ship both.
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync, readFileSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';
import { deflateRawSync, gzipSync } from 'node:zlib';
import {
  RULE_CWE, RULE_SEV, walkPickle, zipMembers, zipRead, scanModelBuffer, scanDatasetYaml,
  scanDatasetJson, scanPython, scanTree, skipPaths, scanKerasZip, scanH5Buffer, scanGraphBuffer,
  scanGraphText, findLambdaLayers, findConfigBlobs, isHdf5, TF_FILE_OPS, TF_PYTHON_OPS,
} from '../model-artefacts.mjs';

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const SCANNER = join(REPO, 'bin', 'model-artefacts.mjs');

const b = (...parts) => Buffer.concat(parts.map((p) => (Buffer.isBuffer(p) ? p : Buffer.from(p, 'latin1'))));
const u16 = (n) => { const x = Buffer.alloc(2); x.writeUInt16LE(n); return x; };
const u32 = (n) => { const x = Buffer.alloc(4); x.writeUInt32LE(n); return x; };
const u64 = (n) => { const x = Buffer.alloc(8); x.writeBigUInt64LE(BigInt(n)); return x; };
const binunicode = (s) => b('X', u32(Buffer.byteLength(s)), s);
const shortUnicode = (s) => b('\x8c', Buffer.from([Buffer.byteLength(s)]), s);

// protocol 2: GLOBAL os.system, BINPUT, BINUNICODE 'true', BINPUT, TUPLE1, BINPUT, REDUCE, BINPUT, STOP
const EVIL_P2 = b('\x80\x02', 'cos\nsystem\n', 'q\x00', binunicode('true'), 'q\x01', '\x85', 'q\x02', 'R', 'q\x03', '.');
// protocol 0: the text form
const EVIL_P0 = b('cos\nsystem\n', 'p0\n', '(', "S'true'\n", 'p1\n', 't', 'p2\n', 'R', 'p3\n', '.');
// protocol 4, framed: SHORT_BINUNICODE x2, MEMOIZE, STACK_GLOBAL, arg, TUPLE1, REDUCE
const P4_BODY = b(shortUnicode('subprocess'), '\x94', shortUnicode('check_output'), '\x94', '\x93', '\x94',
  shortUnicode('id'), '\x94', '\x85', '\x94', 'R', '\x94', '.');
const EVIL_P4 = b('\x80\x04', '\x95', u64(P4_BODY.length), P4_BODY);
// NEWOBJ path: STACK_GLOBAL builtins.getattr, EMPTY_TUPLE, NEWOBJ
const EVIL_NEWOBJ = b('\x80\x04', shortUnicode('builtins'), shortUnicode('getattr'), '\x93', ')', '\x81', '.');
// INST path (protocol 0)
const EVIL_INST = b('(', 'iimportlib\nimport_module\n', '.');
// a memoised module name re-fetched through BINGET before STACK_GLOBAL
const EVIL_MEMO = b('\x80\x04', shortUnicode('runpy'), 'q\x07', '0', 'h\x07', shortUnicode('run_path'), '\x93', ')', 'R', '.');
// benign: {'name': 'linear', 'weights': [0.5], 'n': 3}
const f64 = (v) => { const x = Buffer.alloc(8); x.writeDoubleBE(v); return x; };
const BENIGN_P2 = b('\x80\x02', '}', 'q\x00', '(', binunicode('name'), 'q\x01', binunicode('linear'), 'q\x02',
  binunicode('weights'), 'q\x03', ']', 'q\x04', '(', 'G', f64(0.5), 'e', binunicode('n'), 'q\x05', 'K\x03', 'u', '.');
// benign but naming a NON-dangerous global: collections.OrderedDict via STACK_GLOBAL + REDUCE
const BENIGN_GLOBAL = b('\x80\x04', shortUnicode('collections'), shortUnicode('OrderedDict'), '\x93', ')', 'R', '.');
// a protocol-4 stream carrying torch's persistent-id shape: BINPERSID over a tuple
const BENIGN_PERSID = b('\x80\x04', shortUnicode('storage'), '\x85', 'Q', '.');

function makeZip(entries) {
  const locals = []; const centrals = []; let offset = 0;
  for (const e of entries) {
    const name = Buffer.from(e.name, 'utf8');
    const data = e.deflate ? deflateRawSync(e.data) : e.data;
    const method = e.deflate ? 8 : 0;
    const local = b(u32(0x04034b50), u16(20), u16(0), u16(method), u16(0), u16(0), u32(0), u32(data.length), u32(e.data.length),
      u16(name.length), u16(e.padExtra || 0), name, Buffer.alloc(e.padExtra || 0), data);
    centrals.push(b(u32(0x02014b50), u16(20), u16(20), u16(0), u16(method), u16(0), u16(0), u32(0), u32(data.length), u32(e.data.length),
      u16(name.length), u16(0), u16(0), u16(0), u16(0), u32(0), u32(offset), name));
    locals.push(local); offset += local.length;
  }
  const cd = b(...centrals);
  const eocd = b(u32(0x06054b50), u16(0), u16(0), u16(entries.length), u16(entries.length), u32(cd.length), u32(offset), u16(0));
  return b(...locals, cd, eocd);
}

const safetensors = (headerObj, payload = Buffer.alloc(4)) => {
  const h = Buffer.from(JSON.stringify(headerObj)); return b(u64(h.length), h, payload);
};

const DIRTY_YAML = `configs:
  - config_name: default
    data_files:
      - split: train
        path: "{{ lookup('file', '/etc/passwd') }}"
      - split: test
        path: s3://bucket.invalid/test.parquet
`;
const CLEAN_YAML = `configs:
  - config_name: default
    data_files:
      - split: train
        path: data/train-*.parquet
description: "braces in prose {{ are not a loader template"
`;
const DIRTY_PY = `from transformers import AutoModel
m = AutoModel.from_pretrained("org/model",
    trust_remote_code=True)
d = load_dataset("org/ds", revision="main")
h = hf_hub_download("org/m", "f.bin", revision=REV)
# from_pretrained("commented", trust_remote_code=True)
`;
const CLEAN_PY = `m = AutoModel.from_pretrained("org/model", revision="0123456789abcdef0123456789abcdef01234567", trust_remote_code=False)
s = "trust_remote_code=True inside a string is prose"
x = snapshot_download(repo_id="org/m", revision='fedcba9876543210fedcba9876543210fedcba98')
`;

// Keras configs: a Lambda layer's function body is never present in these fixtures — detection keys
// on class_name, and the bytes under test carry no serialised code.
const LAMBDA_CFG = JSON.stringify({ class_name: 'Sequential', config: { name: 'seq', layers: [
  { class_name: 'InputLayer', config: { name: 'in' } },
  { class_name: 'Lambda', config: { name: 'bad<layer>\u202e', function: 'inert-placeholder' } },
  { class_name: 'Dense', config: { name: 'out', units: 1 } },
] } });
const DENSE_CFG = JSON.stringify({ class_name: 'Sequential', config: { name: 'seq', layers: [
  { class_name: 'Dense', config: { name: 'out', units: 1 } },
] } });
const kerasZip = (cfg, extra = []) => makeZip([{ name: 'metadata.json', data: Buffer.from('{"keras_version":"3.0.0"}') }, ...(cfg == null ? [] : [{ name: 'config.json', data: Buffer.from(cfg) }]), ...extra]);
// A Keras-2 style H5: signature, an object-header-shaped gap, the model_config attribute name
// (null-terminated, 8-padded), a datatype/dataspace-shaped gap, then the JSON as attribute data.
const HDF5_SIG = Buffer.from([0x89, 0x48, 0x44, 0x46, 0x0d, 0x0a, 0x1a, 0x0a]);
// fact: h5py writes a str attribute as a variable-length string whose data is a 16-byte heap id, and the bytes live in a GCOL collection elsewhere / the inline layout is what a fixed-length string attribute looks like (expiry: never, prev: not built)
// fact: neither fixture carries a superblock table, object headers or B-trees the walker would parse / it parses none — the fixture is evidence for the blob search only, not for HDF5 conformance (expiry: when a real Keras-2 .h5 is checked in, prev: not built)
// Two storages, one heuristic. 'inline': a fixed-length string attribute — name (8-padded), datatype
// and dataspace messages, then the JSON as the attribute data. 'vlen': what h5py writes for a Python
// str — the attribute data is a 16-byte global-heap id (collection address + object index) and the
// JSON sits in a GCOL collection later in the file, after an object header the reader never parses.
const h5 = (cfgs, { userBlock = 0, sig = true, storage = 'inline' } = {}) => {
  const attrs = []; const heap = [];
  for (const c of cfgs) {
    const json = Buffer.from(c);
    if (storage === 'inline') attrs.push(Buffer.from('model_config\0\0\0\0', 'latin1'), Buffer.alloc(24, 0x01), json, Buffer.alloc(16));
    else {
      const heapId = Buffer.alloc(16); heapId.writeUInt32LE(json.length, 0); heapId.writeBigUInt64LE(BigInt(4096), 4); heapId.writeUInt16LE(heap.length + 1, 12);
      attrs.push(Buffer.from('model_config\0\0\0\0', 'latin1'), Buffer.alloc(24, 0x02), heapId, Buffer.alloc(16));
      const objHdr = Buffer.alloc(16); objHdr.writeUInt16LE(heap.length + 1, 0); objHdr.writeBigUInt64LE(BigInt(json.length), 8);
      heap.push(objHdr, json, Buffer.alloc((8 - (json.length % 8)) % 8));
    }
  }
  const body = b(...attrs);
  const gcol = heap.length ? b(Buffer.from('GCOL', 'latin1'), Buffer.from([1, 0, 0, 0]), Buffer.alloc(8), ...heap) : Buffer.alloc(0);
  return b(Buffer.alloc(userBlock), sig ? HDF5_SIG : Buffer.alloc(8), Buffer.alloc(96), body, Buffer.alloc(gcol.length ? 512 : 0, 0x00), gcol);
};
// NodeDef bytes: field 1 name (0x0a), field 2 op (0x12); a graph is a sequence of such messages.
const node = (name, op) => b(Buffer.from([0x0a, name.length]), name, Buffer.from([0x12, op.length]), op);
const GRAPH_DIRTY = b(node('x', 'Placeholder'), node('r', 'ReadFile'), node('w', 'WriteFile'), node('p', 'PyFunc'), node('ReadFile', 'Const'));
const GRAPH_CLEAN = b(node('x', 'Placeholder'), node('m', 'MatMul'), node('ReadFile', 'Const'));
const PBTXT_DIRTY = 'node {\n  name: "r"\n  op: "ReadFile"\n}\nnode {\n  name: "e"\n  op: "EagerPyFunc"\n}\n';
const PBTXT_CLEAN = 'node {\n  name: "c"\n  op: "Const"\n}\n';

function tree(files) {
  const dir = mkdtempSync(join(tmpdir(), 'cw-model-artefacts-'));
  for (const [rel, data] of Object.entries(files)) {
    mkdirSync(dirname(join(dir, rel)), { recursive: true });
    writeFileSync(join(dir, rel), data);
  }
  return dir;
}
const withEnv = (env, fn) => {
  const saved = {};
  for (const k of Object.keys(env)) { saved[k] = process.env[k]; if (env[k] == null) delete process.env[k]; else process.env[k] = env[k]; }
  try { return fn(); } finally { for (const k of Object.keys(env)) { if (saved[k] == null) delete process.env[k]; else process.env[k] = saved[k]; } }
};
const scan = (dir) => withEnv({ CW_MODELSCAN: 'off', CW_MODEL_SKIP_PATHS: undefined }, () => scanTree(dir));
const rules = (r) => r.findings.map((f) => `${f.rule}@${f.path}`).sort();

describe('pickle opcode walker', () => {
  test('protocol 0, 2 and framed 4 all resolve os/subprocess globals through REDUCE', () => {
    for (const [name, buf, mod, via] of [['p0', EVIL_P0, 'os', 'GLOBAL'], ['p2', EVIL_P2, 'os', 'GLOBAL'], ['p4', EVIL_P4, 'subprocess', 'STACK_GLOBAL']]) {
      const r = walkPickle(buf);
      assert.equal(r.ok, true, `${name}: ${r.error}`);
      assert.equal(r.globals.length, 1, name);
      assert.equal(r.globals[0].module, mod, name);
      assert.equal(r.globals[0].via, via, name);
      assert.equal(r.globals[0].reduced, true, `${name}: REDUCE was not attributed to the global`);
      assert.equal(r.reduce, 1, name);
    }
  });
  test('NEWOBJ, INST and a memo-fetched module name are all attributed', () => {
    const n = walkPickle(EVIL_NEWOBJ);
    assert.equal(n.ok, true, n.error);
    assert.deepEqual([n.globals[0].module, n.globals[0].name, n.globals[0].built], ['builtins', 'getattr', true]);
    const i = walkPickle(EVIL_INST);
    assert.equal(i.ok, true, i.error);
    assert.deepEqual([i.globals[0].module, i.globals[0].via, i.globals[0].built], ['importlib', 'INST', true]);
    const m = walkPickle(EVIL_MEMO);
    assert.equal(m.ok, true, m.error);
    assert.deepEqual([m.globals[0].module, m.globals[0].name], ['runpy', 'run_path']);
  });
  test('benign streams walk to STOP with no globals, or with a global that is not dangerous', () => {
    const p = walkPickle(BENIGN_P2);
    assert.equal(p.ok, true, p.error);
    assert.equal(p.globals.length, 0);
    assert.equal(p.opcodes, 20);
    const g = walkPickle(BENIGN_GLOBAL);
    assert.equal(g.ok, true, g.error);
    assert.equal(g.globals[0].module, 'collections');
    assert.equal(scanModelBuffer(BENIGN_GLOBAL).dangerous.length, 0, 'collections.OrderedDict is not a dangerous global');
    const q = walkPickle(BENIGN_PERSID);
    assert.equal(q.ok, true, q.error);
  });
  test('a truncated or non-pickle stream is an ERROR, never a clean walk', () => {
    const t = walkPickle(EVIL_P2.subarray(0, 18));   // cut inside the BINUNICODE argument, after GLOBAL
    assert.equal(t.ok, false);
    assert.match(t.error, /truncated|no STOP|unterminated/);
    assert.equal(t.globals.length, 1, 'the global read before the truncation is still reported');
    const raw = walkPickle(Buffer.from([0xc8, 0xff, 0x00, 0x12]));
    assert.equal(raw.ok, false);
    assert.match(raw.error, /unknown opcode/);
    assert.equal(walkPickle(Buffer.alloc(0)).ok, false);
  });
});

describe('zip-wrapped checkpoints', () => {
  test('a STORED data.pkl and a DEFLATE data.pkl are both opened and walked', () => {
    for (const deflate of [false, true]) {
      const z = makeZip([
        { name: 'archive/version', data: Buffer.from('3\n') },
        { name: 'archive/data.pkl', data: EVIL_P2, deflate, padExtra: 12 },
        { name: 'archive/data/0', data: Buffer.alloc(16) },
      ]);
      const members = zipMembers(z);
      assert.equal(members.length, 3);
      assert.equal(zipRead(z, members[1]).equals(EVIL_P2), true, `deflate=${deflate}: member bytes differ`);
      const acc = scanModelBuffer(z);
      assert.equal(acc.kind, 'zip');
      assert.equal(acc.members, 1);
      assert.equal(acc.dangerous.length, 1, `deflate=${deflate}: ${JSON.stringify(acc.errors)}`);
      assert.equal(acc.dangerous[0].member, 'archive/data.pkl');
      assert.deepEqual(acc.errors, []);
    }
  });
  test('a zip whose central directory is unreadable is an ERROR for the file, not a clean zip', () => {
    const z = makeZip([{ name: 'archive/data.pkl', data: BENIGN_P2 }]);
    const cut = z.subarray(0, z.length - 10);
    const acc = scanModelBuffer(cut);
    assert.equal(acc.kind, 'zip');
    assert.ok(acc.errors.length >= 1, 'a torn zip must state it could not be read');
  });
  test('gzip-wrapped pickles (joblib) are inflated and walked', () => {
    const acc = scanModelBuffer(gzipSync(EVIL_P2));
    assert.equal(acc.kind, 'gzip+pickle');
    assert.equal(acc.dangerous.length, 1);
  });
});

describe('dataset configs and python', () => {
  test('yaml: the template and the remote scheme are found under data_files; prose braces are not published', () => {
    const d = scanDatasetYaml(DIRTY_YAML);
    assert.equal(d.hits.template.length, 1);
    assert.match(d.hits.template[0], /configs\.data_files\.path line 5/);
    assert.equal(d.hits.remote.length, 1);
    assert.match(d.hits.remote[0], /^s3:\/\/ at configs\.data_files\.path line 7/);
    const c = scanDatasetYaml(CLEAN_YAML);
    assert.deepEqual([c.hits.template, c.hits.remote, c.hits.templateInProse], [[], [], 1]);
  });
  test('json: dataset_infos template and reference:// in a data path; download_checksums URLs are not a data path', () => {
    const r = scanDatasetJson(JSON.stringify({ default: {
      download_checksums: { 'https://example.invalid/x': { num_bytes: 1 } },
      data_files: [{ path: 'reference://spec.json' }],
      splits: { train: { name: '{{ 7 * 7 }}' } },
    } }));
    assert.equal(r.hits.template.length, 1);
    assert.equal(r.hits.remote.length, 1);
    assert.match(r.hits.remote[0], /^reference:\/\/ at default\.data_files\.0\.path/);
    assert.equal(scanDatasetJson('{not json').unreadable, 'not JSON');
  });
  test('python: trust_remote_code=True and an unpinned or branch-named revision fire; a sha pins; strings and comments do not', () => {
    const d = scanPython(DIRTY_PY);
    assert.deepEqual(d.trust, [3]);
    assert.equal(d.unpinned.length, 2, JSON.stringify(d.unpinned));
    assert.match(d.unpinned[0], /from_pretrained line 2 \(no revision=\)/);
    assert.match(d.unpinned[1], /load_dataset line 4 \(revision is a branch or tag/);
    assert.equal(d.nonLiteral, 1, 'revision=REV is undeterminable and is counted, not published');
    const c = scanPython(CLEAN_PY);
    assert.deepEqual([c.trust, c.unpinned, c.nonLiteral], [[], [], 0]);
  });
});

describe('keras configs and tensorflow graphs', () => {
  test('.keras: a Lambda in config.json fires with a sanitised, capped layer name; Dense-only and no-config archives do not', () => {
    const r = scanKerasZip(kerasZip(LAMBDA_CFG));
    assert.equal(r.config, true);
    assert.deepEqual(r.layers, ['bad_layer__']);
    assert.equal(r.unreadable, null);
    assert.deepEqual(scanKerasZip(kerasZip(DENSE_CFG)).layers, []);
    const none = scanKerasZip(kerasZip(null));
    assert.equal(none.config, false, 'a weights-only .keras has no config to judge');
    assert.match(scanKerasZip(kerasZip('{not json')).unreadable, /not JSON/);
    assert.match(scanKerasZip(Buffer.from('PK\x03\x04 torn')).unreadable, /end-of-central-directory/);
  });
  test('findLambdaLayers walks nested models and arrays; a Lambda with no name is (unnamed)', () => {
    const cfg = { class_name: 'Functional', config: { layers: [{ class_name: 'Model', config: { layers: [{ class_name: 'Lambda' }] } }] } };
    assert.deepEqual(findLambdaLayers(cfg), ['(unnamed)']);
    assert.deepEqual(findLambdaLayers({ class_name: 'LambdaCallback' }), [], 'class_name is matched exactly');
  });
  test('h5: every config blob is walked whether stored inline or in the global heap; a user block is honoured; no signature or torn JSON is unreadable, never clean', () => {
    for (const storage of ['inline', 'vlen']) {
      const r = scanH5Buffer(h5([DENSE_CFG, LAMBDA_CFG], { storage }));
      assert.equal(r.hdf5, true, storage);
      assert.equal(r.declared, true, storage);
      assert.equal(r.configs, 2, `${storage}: ${r.unreadable}`);
      assert.deepEqual(r.layers, ['bad_layer__'], `${storage}: the Lambda in the SECOND config is found`);
      assert.equal(r.unreadable, null, storage);
    }
    const declaredOnly = scanH5Buffer(b(HDF5_SIG, Buffer.alloc(64), Buffer.from('model_config\0', 'latin1'), Buffer.alloc(64)));
    assert.equal(declaredOnly.declared, true);
    assert.match(declaredOnly.unreadable, /declared but no JSON config located/, 'a declared config the heuristic cannot find is stated, not clean');
    const r = scanH5Buffer(h5([DENSE_CFG, LAMBDA_CFG]));
    const ub = scanH5Buffer(h5([LAMBDA_CFG], { userBlock: 512 }));
    assert.equal(ub.hdf5, true);
    assert.equal(ub.layers.length, 1);
    assert.equal(isHdf5(Buffer.alloc(600)), false);
    const nosig = scanH5Buffer(h5([LAMBDA_CFG], { sig: false }));
    assert.equal(nosig.hdf5, false);
    assert.match(nosig.unreadable, /no HDF5 signature/);
    const torn = h5([LAMBDA_CFG]);
    const cut = torn.subarray(0, torn.length - 30);
    assert.match(scanH5Buffer(cut).unreadable, /unterminated/);
    const weightsOnly = scanH5Buffer(b(HDF5_SIG, Buffer.alloc(64)));
    assert.deepEqual([weightsOnly.declared, weightsOnly.configs, weightsOnly.unreadable], [false, 0, null], 'no model_config is a counted absence, not an error');
    const meta = findConfigBlobs(b(Buffer.from('\x0a\x40', 'latin1'), Buffer.from(LAMBDA_CFG), Buffer.from('\x12\x05other', 'latin1'), Buffer.from(DENSE_CFG)));
    assert.equal(meta.blobs.length, 2, 'blobs embedded in protobuf strings are located by their opening');
    assert.equal(findConfigBlobs(b(Buffer.from(LAMBDA_CFG), Buffer.alloc(9), Buffer.from(LAMBDA_CFG))).blobs.length, 1, 'the same config at two offsets is one config');
    assert.deepEqual(meta.blobs[0].layers, ['bad_layer__']);
  });
  test('protobuf graphs: ReadFile/WriteFile and PyFunc ops are found by their NodeDef signature; a node NAMED ReadFile is not an op', () => {
    const d = scanGraphBuffer(GRAPH_DIRTY);
    assert.deepEqual(d.hits, { ReadFile: 1, WriteFile: 1, PyFunc: 1 });
    assert.equal(d.opsSeen, 5);
    const c = scanGraphBuffer(GRAPH_CLEAN);
    assert.deepEqual(c.hits, {});
    assert.equal(c.opsSeen, 3);
    assert.equal(scanGraphBuffer(Buffer.from('no tags here')).opsSeen, 0);
    assert.deepEqual(scanGraphText(PBTXT_DIRTY).hits, { ReadFile: 1, EagerPyFunc: 1 });
    assert.deepEqual(scanGraphText(PBTXT_CLEAN), { opsSeen: 1, hits: {} });
    assert.deepEqual([...TF_FILE_OPS], ['ReadFile', 'WriteFile']);
    assert.deepEqual([...TF_PYTHON_OPS], ['PyFunc', 'PyFuncStateless', 'EagerPyFunc']);
  });
  test('a zip member whose declared inflated size exceeds the cap is refused before inflating', () => {
    const z = makeZip([{ name: 'archive/data.pkl', data: EVIL_P2, deflate: true }]);
    const m = zipMembers(z)[0];
    assert.throws(() => zipRead(z, m, 10), /inflated bytes, over the 10-byte cap/);
    const acc = withEnv({ CW_MODEL_MAX_BYTES: '10' }, () => scanModelBuffer(z));
    assert.equal(acc.dangerous.length, 0);
    assert.match(acc.errors[0], /over the 10-byte cap/, 'a refused member is an error on the file, never a clean walk');
  });
});

describe('real Keras 3.15 / TensorFlow 2.21 artefacts under fixtures/scan-canary/*/real', () => {
  const real = (d) => join(REPO, 'fixtures', 'scan-canary', d, 'real');
  const read = (d, f) => readFileSync(join(real(d), f));
  test('h5: the real legacy file declares model_config as a heap-stored vlen string and the Lambda is located anyway', () => {
    const r = scanH5Buffer(read('dirty', 'real_legacy.h5'));
    assert.deepEqual([r.hdf5, r.declared, r.configs, r.layers, r.unreadable], [true, true, 1, ['real_lambda'], null]);
    const c = scanH5Buffer(read('clean', 'real_legacy.h5'));
    assert.deepEqual([c.declared, c.configs, c.layers], [true, 1, []]);
    const bytes = read('dirty', 'real_legacy.h5');
    const at = bytes.indexOf(Buffer.from('model_config\0', 'latin1'));
    assert.ok(at >= 0 && bytes.indexOf(0x7b, at) - at > 256, 'the JSON is NOT adjacent to the attribute name — the storage fact the search must not assume');
  });
  test('.keras and SavedModel: DEFLATE config.json and a real graph resolve to the same rules as the hand-built plants', () => {
    const k = scanKerasZip(read('dirty', 'real.keras'));
    assert.deepEqual([k.config, k.layers, k.unreadable], [true, ['real_lambda'], null]);
    assert.deepEqual(scanKerasZip(read('clean', 'real.keras')).layers, []);
    const g = scanGraphBuffer(read('dirty', 'real_savedmodel/saved_model.pb'));
    assert.deepEqual(g.hits, { ReadFile: 1, EagerPyFunc: 2 });
    assert.ok(g.opsSeen > 20, 'a real graph shows many op-shaped strings');
    assert.deepEqual(scanGraphBuffer(read('clean', 'real_savedmodel/saved_model.pb')).hits, {});
  });
  test('scanTree: fingerprint.pb is not a graph surface, so the clean export counts no node-less graph', () => {
    const r = scan(real('clean'));
    assert.deepEqual(r.findings, []);
    assert.deepEqual([r.summary.surfaces.kerasConfigs, r.summary.surfaces.tfGraphs, r.summary.tfGraphsWithoutNodes, r.summary.kerasWithoutConfig], [2, 1, 0, 0]);
    assert.equal(rules(scan(real('dirty'))).length, 4);
  });
});

describe('scanTree over a fixture tree — every rule, both directions', () => {
  const dirty = tree({
    'model.pkl': EVIL_P2,
    'weights/ckpt.pt': makeZip([{ name: 'archive/data.pkl', data: EVIL_P4, deflate: true }]),
    'weights/bad.safetensors': b(u64(1e9), Buffer.from('{}')),
    'weights/notjson.safetensors': b(u64(5), Buffer.from('nope!'), Buffer.alloc(4)),
    'dataset.yaml': DIRTY_YAML,
    'dataset_infos.json': JSON.stringify({ default: { data_files: [{ path: 'gs://bucket/x' }, { path: '${HOME}/x' }] } }),
    'README.md': '---\nconfigs:\n  - config_name: x\n    data_files: "{% include x %}"\n---\n# card\n',
    'src/load.py': DIRTY_PY,
    'weights/raw.bin': Buffer.from([0xc8, 0xff, 0x00, 0x12, 0x99]),
    'node_modules/dep/model.pkl': EVIL_P2,
    'keras/model.keras': kerasZip(LAMBDA_CFG),
    'keras/legacy.h5': h5([LAMBDA_CFG], { storage: 'vlen' }),
    'keras/weights.hdf5': b(HDF5_SIG, Buffer.alloc(32)),
    'saved/saved_model.pb': GRAPH_DIRTY,
    'saved/keras_metadata.pb': Buffer.from('\x0a\x40{"class_name": "Lambda", "config": {"name": "l"}}'),
    'saved/graph.pbtxt': PBTXT_DIRTY,
    'saved/other.pb': Buffer.from('\x0a\x03abc'),
  });
  const clean = tree({
    'model.pkl': BENIGN_P2,
    'weights/ckpt.pt': makeZip([{ name: 'archive/data.pkl', data: BENIGN_P2 }, { name: 'archive/data/0', data: Buffer.alloc(8) }]),
    'weights/good.safetensors': safetensors({ __metadata__: { format: 'pt' }, w: { dtype: 'F32', shape: [1], data_offsets: [0, 4] } }),
    'dataset.yaml': CLEAN_YAML,
    'dataset_infos.json': JSON.stringify({ default: { data_files: [{ path: 'data/train.parquet' }], description: 'plain' } }),
    'README.md': '# no front matter, mentions {{ braces }} in prose\n',
    'src/load.py': CLEAN_PY,
    'package.json': '{"name":"x","scripts":{"x":"{{ not a dataset }}"}}',
    'keras/model.keras': kerasZip(DENSE_CFG),
    'keras/legacy.h5': h5([DENSE_CFG]),
    'saved/saved_model.pb': GRAPH_CLEAN,
    'saved/graph.pbtxt': PBTXT_CLEAN,
  });
  test('DIRTY: every rule fires, sorted by (path, rule), each row carrying sev and cwe', () => {
    const r = scan(dirty);
    assert.equal(r.tool, 'model-artefacts');
    assert.deepEqual(rules(r), [
      'dataset-config-remote-scheme@dataset.yaml', 'dataset-config-remote-scheme@dataset_infos.json',
      'dataset-config-template@README.md', 'dataset-config-template@dataset.yaml', 'dataset-config-template@dataset_infos.json',
      'hf-trust-remote-code@src/load.py', 'hf-unpinned-revision@src/load.py',
      'keras-lambda-layer@keras/legacy.h5', 'keras-lambda-layer@keras/model.keras',
      'pickle-dangerous-global@model.pkl', 'pickle-dangerous-global@weights/ckpt.pt',
      'safetensors-header-invalid@weights/bad.safetensors', 'safetensors-header-invalid@weights/notjson.safetensors',
      'keras-lambda-layer@saved/keras_metadata.pb', 'tf-graph-file-op@saved/graph.pbtxt', 'tf-graph-python-op@saved/graph.pbtxt',
      'tf-graph-file-op@saved/saved_model.pb', 'tf-graph-python-op@saved/saved_model.pb',
    ].sort());
    assert.deepEqual(r.findings.map((f) => `${f.path}|${f.rule}`), r.findings.map((f) => `${f.path}|${f.rule}`).slice().sort(), 'not sorted');
    for (const f of r.findings) {
      assert.equal(f.sev, RULE_SEV[f.rule]);
      assert.equal(f.cwe, RULE_CWE[f.rule]);
      assert.ok(['crit', 'high', 'med', 'low'].includes(f.sev));
    }
    assert.equal(r.summary.findings, 18);
    assert.equal(r.summary.kerasWithoutConfig, 1, 'the weights-only hdf5 is a counted absence');
    assert.deepEqual(r.summary.kerasWithoutConfigFiles, ['keras/weights.hdf5']);
    assert.equal(r.summary.tfGraphsWithoutNodes, 1, 'a .pb with no op-shaped string is counted, not clean');
    assert.deepEqual(r.summary.tfGraphsWithoutNodesFiles, ['saved/other.pb']);
    assert.match(r.findings.find((f) => f.path === 'keras/model.keras').detail, /bad_layer__/);
    assert.match(r.findings.find((f) => f.path === 'saved/keras_metadata.pb').detail, /1 Lambda layer\(s\) in 1 config blob\(s\).*: l /);
    assert.match(r.findings.find((f) => f.rule === 'tf-graph-file-op' && f.path === 'saved/saved_model.pb').detail, /ReadFile ×1, WriteFile ×1; 5 op-shaped/);
    assert.deepEqual(Object.keys(r.summary.byRule), Object.keys(r.summary.byRule).slice().sort());
    assert.equal(r.summary.byRule['pickle-dangerous-global'], 2);
    assert.equal(r.summary.unreadable, 1, 'raw.bin has a magic the walker cannot read and must be COUNTED');
    assert.equal(r.summary.unreadableFiles[0].path, 'weights/raw.bin');
    assert.equal(r.summary.filesScanned, 16);
    assert.ok(!rules(r).some((x) => x.includes('node_modules')), 'excluded dirs are not walked');
  });
  test('DIRTY: the report names modules, opcode counts and key paths — never file contents', () => {
    const text = JSON.stringify(scan(dirty));
    assert.ok(text.includes('os.system'), 'the dangerous global is named');
    assert.ok(text.includes('subprocess.check_output'));
    assert.ok(!text.includes('/etc/passwd'), 'the template body must not be echoed');
    assert.ok(!text.includes('bucket.invalid'), 'the remote URL must not be echoed');
    assert.ok(!text.includes('org/model'), 'python source must not be echoed');
    assert.ok(!text.includes('inert-placeholder'), 'the Lambda function field is never echoed');
    assert.ok(!text.includes('bad<layer>') && !text.includes('\u202e'), 'a layer name is sanitised before it is reported');
  });
  test('CLEAN: the same surfaces are examined and nothing fires', () => {
    const r = scan(clean);
    assert.deepEqual(r.findings, []);
    assert.equal(r.summary.filesScanned, 10, JSON.stringify(r.summary));
    assert.deepEqual(r.summary.surfaces, { modelArtefacts: 2, safetensors: 1, datasetConfigs: 2, python: 1, kerasConfigs: 2, tfGraphs: 2 });
    assert.deepEqual([r.summary.kerasWithoutConfig, r.summary.tfGraphsWithoutNodes], [0, 0]);
    assert.equal(r.summary.unreadable, 0);
    assert.equal(r.summary.pickleMembersWalked, 2);
    assert.equal(r.summary.templateInProse, 1);
  });
  test('an empty tree is a declared void: filesScanned 0', () => {
    const empty = tree({ 'index.mjs': 'export {};\n' });
    const r = scan(empty);
    assert.equal(r.summary.filesScanned, 0);
    assert.deepEqual(r.findings, []);
    rmSync(empty, { recursive: true, force: true });
  });
  test('over-cap files are skippedOversize, declared by path, and produce no finding', () => {
    const r = withEnv({ CW_MODEL_MAX_BYTES: '20', CW_MODELSCAN: 'off', CW_MODEL_SKIP_PATHS: undefined }, () => scanTree(dirty));
    assert.ok(r.summary.skippedOversize >= 2, JSON.stringify(r.summary));
    assert.ok(r.summary.oversizeFiles.some((o) => o.path === 'model.pkl'));
    assert.ok(!rules(r).includes('pickle-dangerous-global@model.pkl'), 'a skipped file cannot be judged');
    assert.equal(r.summary.maxBytes, 20, 'the cap is read at call time');
  });
  test('CW_MODEL_SKIP_PATHS skips the named root-relative directory and says so', () => {
    const r = withEnv({ CW_MODEL_SKIP_PATHS: 'weights, src/', CW_MODELSCAN: 'off' }, () => scanTree(dirty));
    assert.deepEqual(r.summary.skippedPaths, ['src', 'weights']);
    assert.ok(!rules(r).some((x) => x.startsWith('pickle-dangerous-global@weights') || x.includes('src/load.py')));
    assert.deepEqual(withEnv({ CW_MODEL_SKIP_PATHS: undefined }, skipPaths), ['fixtures/scan-canary/dirty']);
  });
  test('the CLI: exit 0 with the report on stdout, byte-identical across runs; exit 2 for a missing root', () => {
    const env = { ...process.env, CW_MODELSCAN: 'off' };
    const a = execFileSync(process.execPath, [SCANNER, dirty], { env, encoding: 'utf8' });
    const c = execFileSync(process.execPath, [SCANNER, dirty], { env, encoding: 'utf8' });
    assert.equal(a, c, 'two runs over the same tree must be byte-identical');
    assert.equal(JSON.parse(a).summary.secondWitness.state, 'off');
    let status = 0;
    try { execFileSync(process.execPath, [SCANNER, join(dirty, 'does-not-exist')], { env, stdio: 'pipe' }); } catch (e) { status = e.status; }
    assert.equal(status, 2, 'an unreadable root is could-not-run, exit 2');
  });
  test('an absent modelscan is a stated absence, never a failure of the lane', () => {
    const env = { ...process.env, CW_MODELSCAN: join(dirty, 'no-such-modelscan') };
    const out = JSON.parse(execFileSync(process.execPath, [SCANNER, clean], { env, encoding: 'utf8' }));
    assert.deepEqual(out.summary.secondWitness, { tool: 'modelscan', state: 'absent' });
    assert.deepEqual(out.findings, []);
  });
  test('RULE_CWE and RULE_SEV cover exactly the rules the scanner can emit', () => {
    const emitted = new Set(scan(dirty).findings.map((f) => f.rule));
    assert.deepEqual([...emitted].sort(), Object.keys(RULE_CWE).sort());
    assert.deepEqual(Object.keys(RULE_SEV).sort(), Object.keys(RULE_CWE).sort());
    for (const c of Object.values(RULE_CWE)) assert.match(c, /^CWE-\d+$/);
  });
  test.after(() => { rmSync(dirty, { recursive: true, force: true }); rmSync(clean, { recursive: true, force: true }); });
});

// Measured 2026-09-16: 5 of 5 model-artefacts rows on commitwork named a copy under .claude/worktrees/.
test('a plant under .claude/worktrees/<name>/ is neither scanned nor named; a bare worktrees/ still is', () => {
  const d = mkdtempSync(join(tmpdir(), 'cw-model-wt-'));
  for (const rel of ['dataset.yaml', '.claude/worktrees/agent-x/dataset.yaml', 'worktrees/x/dataset.yaml']) {
    mkdirSync(dirname(join(d, rel)), { recursive: true });
    writeFileSync(join(d, rel), rel === 'dataset.yaml' ? CLEAN_YAML : DIRTY_YAML);
  }
  try {
    const r = scan(d);
    assert.equal(r.summary.filesScanned, 2, 'the root file and the bare worktrees/ plant; the nested worktree is not walked');
    assert.ok(!r.findings.some((f) => f.path.startsWith('.claude/worktrees/')), JSON.stringify(r.findings));
    assert.ok(r.findings.some((f) => f.path === 'worktrees/x/dataset.yaml'));
  } finally { rmSync(d, { recursive: true, force: true }); }
});
